package com.valor.auth;
import com.valor.communication.RegistrationEmailSender;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.security.SecureRandom;import java.time.*;import java.util.*;
@Service class EmailRegistrationService {
 private final EmailRegistrationRepository registrations;private final UserRepo users;private final CustomerRepo customers;private final PasswordEncoder encoder;private final RegistrationEmailSender mail;private final SecureRandom random=new SecureRandom();
 EmailRegistrationService(EmailRegistrationRepository r,UserRepo u,CustomerRepo c,PasswordEncoder e,RegistrationEmailSender m){registrations=r;users=u;customers=c;encoder=e;mail=m;}
 @Transactional EmailRegistrationDtos.Started start(EmailRegistrationDtos.Start in){String email=norm(in.email());String phone=in.phone()==null?null:normPhone(in.phone());if(users.findByEmail(email).isPresent()||phone!=null&&users.findByPhone(phone).isPresent())throw new IllegalArgumentException("Registration unavailable");var old=registrations.findByEmail(email);if(old.isPresent()&&old.get().expiresAt.isAfter(LocalDateTime.now()))throw new IllegalArgumentException("Registration unavailable");var r=new EmailRegistrationChallenge();r.id=UUID.randomUUID().toString().replace("-","");r.email=email;r.phone=phone;r.passwordHash=encoder.encode(in.password());r.fullName=in.fullName().trim();r.alternatePhone=in.alternatePhone();r.companyName=in.companyName();r.address=in.address();r.hasLift=in.hasLift();r.referralCode=in.referralCode();return deliver(r);}
 @Transactional EmailRegistrationDtos.Started resend(String id){var r=registrations.lock(id).orElseThrow(()->new IllegalArgumentException("Registration unavailable"));var now=LocalDateTime.now();if(r.verifiedAt!=null||r.lockedUntil!=null&&r.lockedUntil.isAfter(now)||r.lastSentAt.isAfter(now.minusSeconds(60)))throw new IllegalArgumentException("Registration unavailable");return deliver(r);}
 @Transactional(noRollbackFor = IllegalArgumentException.class) User verify(String id,String code){var r=registrations.lock(id).orElseThrow(()->new IllegalArgumentException("Verification unavailable"));var now=LocalDateTime.now();if(!"ACCEPTED".equals(r.deliveryStatus)||r.verifiedAt!=null||!r.expiresAt.isAfter(now)||r.attemptsRemaining<=0||r.lockedUntil!=null&&r.lockedUntil.isAfter(now)||!encoder.matches(code,r.otpHash)){if(r.attemptsRemaining>0)r.attemptsRemaining--;if(r.attemptsRemaining<=0)r.lockedUntil=now.plusMinutes(15);registrations.saveAndFlush(r);throw new IllegalArgumentException("Verification unavailable");}if(users.findByEmail(r.email).isPresent()||r.phone!=null&&users.findByPhone(r.phone).isPresent())throw new IllegalArgumentException("Registration unavailable");var u=new User();u.setEmail(r.email);u.setPhone(r.phone);u.setPasswordHash(r.passwordHash);u.setRole(Role.CUSTOMER);users.saveAndFlush(u);var p=new CustomerProfile();p.setUser(u);p.setFullName(r.fullName);p.setReferralCode(r.referralCode==null?"VAL-"+r.id.substring(0,8).toUpperCase(Locale.ROOT):r.referralCode);p.alternatePhone=r.alternatePhone;p.companyName=r.companyName;p.address=r.address;p.hasLift=r.hasLift;customers.saveAndFlush(p);r.verifiedAt=now;r.deliveryStatus="VERIFIED";r.otpHash="invalidated";registrations.save(r);return u;}
 private EmailRegistrationDtos.Started deliver(EmailRegistrationChallenge r){String code=String.format("%06d",random.nextInt(1_000_000));r.otpHash=encoder.encode(code);r.attemptsRemaining=3;r.expiresAt=LocalDateTime.now().plusSeconds(300);r.lastSentAt=LocalDateTime.now();r.deliveryStatus=mail.send(r.email,code)?"ACCEPTED":"FAILED";if("FAILED".equals(r.deliveryStatus))throw new IllegalArgumentException("Email delivery unavailable");registrations.saveAndFlush(r);return new EmailRegistrationDtos.Started(r.id,r.expiresAt,"EMAIL_ACCEPTED");}
 private static String norm(String s){String v=s==null?null:s.trim().toLowerCase(Locale.ROOT);if(v==null||!v.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw new IllegalArgumentException("Invalid email");return v;}
 private static String normPhone(String s){String v=s.trim().replaceAll("[\\s\\-()]","");if(!v.matches("\\+[1-9]\\d{7,14}"))throw new IllegalArgumentException("Invalid phone");return v;}
}
